// Semester Rush (from Volt City) P4 — the IAP catalogue as the game reads it (Resources/data/iap.json, generated by Tools/build_iap.py from
// its product table). Engine-free. Product texts in 10 languages live in the catalogue (Play listing = in-game card, one source);
// prices NEVER: the shop shows only the store's displayPrice ("…" until it arrived).
//   * ad_free = an entitlement in `ad_free_features` (noads) — granted only by Remove Ads / Chancellor Edition /
//     Complete Campus Collection (CLAUDE.md §3/§8). Nothing else decides ads.
//   * Owned(slug): a permanent product is owned when every entitlement it grants is active (a pack whose parts were all
//     bought separately shows "Owned" too — never sell a player what they already have).
using System;
using System.Collections.Generic;
using CoddyKit;

namespace SemesterRush.Game
{
    public sealed class IapProduct
    {
        public string Slug = "", Id = "", Kind = "", Group = "", Icon = "", Slot = "";
        public double Usd;
        /// <summary>Consumables: days of current income x 10 (sim GrantPurchaseFunds uses consumable_days).</summary>
        public int DaysX10;
        public bool AdFree, OfferOnly;
        public readonly List<string> Grants = new List<string>();
        public readonly List<string> Parts = new List<string>();
        public readonly Dictionary<string, string> Title = new Dictionary<string, string>();
        public readonly Dictionary<string, string> Desc = new Dictionary<string, string>();
        public bool Consumable => Kind == "consumable";
    }

    public sealed class OfferRule
    {
        public string Slug = "", Event = "";
        public int DayMin, DayMax = int.MaxValue, PerGame = 1, PerChapter, AwayDaysMin, StarsMax = 3;
    }

    public sealed class IapCatalog
    {
        public string Prefix = "";
        public readonly List<string> Langs = new List<string>();
        public readonly List<string> Order = new List<string>();
        public readonly Dictionary<string, IapProduct> Products = new Dictionary<string, IapProduct>();
        public readonly List<string> Groups = new List<string>();
        public readonly Dictionary<string, Dictionary<string, string>> GroupTitle = new Dictionary<string, Dictionary<string, string>>();
        public readonly List<string> AdFreeFeatures = new List<string>();
        public readonly List<string> AdFreeProducts = new List<string>();
        public readonly List<string> Entitlements = new List<string>();
        public readonly Dictionary<string, OfferRule> Offers = new Dictionary<string, OfferRule>();
        public int OfferCooldownDays = 3, OffersPerSession = 1, DailyPackLimit = 3;
        public readonly List<string> Errors = new List<string>();

        public static IapCatalog Parse(string json)
        {
            var c = new IapCatalog();
            var d = MiniJson.TryParseObject(json);
            if (d == null) { c.Errors.Add("iap.json missing or invalid"); return c; }
            c.Prefix = MiniJson.Str(d, "prefix");
            foreach (var o in MiniJson.Arr(d, "langs") ?? new List<object>()) c.Langs.Add(o as string ?? "");
            foreach (var o in MiniJson.Arr(d, "order") ?? new List<object>()) c.Order.Add(o as string ?? "");
            foreach (var o in MiniJson.Arr(d, "ad_free_features") ?? new List<object>()) c.AdFreeFeatures.Add(o as string ?? "");
            foreach (var o in MiniJson.Arr(d, "ad_free_products") ?? new List<object>()) c.AdFreeProducts.Add(o as string ?? "");
            foreach (var o in MiniJson.Arr(d, "entitlements") ?? new List<object>()) c.Entitlements.Add(o as string ?? "");
            foreach (var o in MiniJson.Arr(d, "groups") ?? new List<object>())
            {
                string id = MiniJson.Str(o, "id");
                c.Groups.Add(id);
                c.GroupTitle[id] = Texts(MiniJson.Obj(o, "title"));
            }
            var products = MiniJson.Obj(d, "products") ?? new Dictionary<string, object>();
            foreach (string slug in c.Order)
            {
                var p = MiniJson.Obj(products, slug);
                if (p == null) { c.Errors.Add("order lists unknown product " + slug); continue; }
                var x = new IapProduct
                {
                    Slug = slug, Id = MiniJson.Str(p, "id", c.Prefix + slug), Kind = MiniJson.Str(p, "kind"), Group = MiniJson.Str(p, "group"),
                    Icon = MiniJson.Str(p, "icon"), Slot = MiniJson.Str(p, "slot"), Usd = MiniJson.Num(p, "usd"),
                    DaysX10 = MiniJson.Int(p, "days_x10"), AdFree = MiniJson.Bool(p, "ad_free"), OfferOnly = MiniJson.Bool(p, "offer_only"),
                };
                foreach (var g in MiniJson.Arr(p, "grants") ?? new List<object>()) x.Grants.Add(g as string ?? "");
                foreach (var g in MiniJson.Arr(p, "parts") ?? new List<object>()) x.Parts.Add(g as string ?? "");
                foreach (var kv in Texts(MiniJson.Obj(p, "title"))) x.Title[kv.Key] = kv.Value;
                foreach (var kv in Texts(MiniJson.Obj(p, "desc"))) x.Desc[kv.Key] = kv.Value;
                c.Products[slug] = x;
            }
            var offers = MiniJson.Obj(d, "offers") ?? new Dictionary<string, object>();
            c.OfferCooldownDays = MiniJson.Int(offers, "cooldown_days", 3);
            c.OffersPerSession = MiniJson.Int(offers, "max_per_session", 1);
            foreach (var kv in offers)
            {
                if (!(kv.Value is Dictionary<string, object> r)) continue;
                c.Offers[kv.Key] = new OfferRule
                {
                    Slug = kv.Key, Event = MiniJson.Str(r, "event"), DayMin = MiniJson.Int(r, "day_min"), DayMax = MiniJson.Int(r, "day_max", int.MaxValue),
                    PerGame = MiniJson.Int(r, "per_game", 1), PerChapter = MiniJson.Int(r, "per_chapter"), AwayDaysMin = MiniJson.Int(r, "away_days_min"),
                    StarsMax = MiniJson.Int(r, "stars_max", 3),
                };
            }
            c.DailyPackLimit = MiniJson.Int(MiniJson.Obj(d, "consumable_policy"), "utc_daily_pack_limit", 3);
            return c;
        }

        static Dictionary<string, string> Texts(Dictionary<string, object> m)
        {
            var o = new Dictionary<string, string>();
            if (m != null) foreach (var kv in m) if (kv.Value is string s) o[kv.Key] = s;
            return o;
        }

        static string Pick(Dictionary<string, string> m, string lang) =>
            m != null && m.TryGetValue(lang ?? "en", out var s) && s != "" ? s : m != null && m.TryGetValue("en", out var e) ? e : "";

        public string Title(string slug, string lang) => Products.TryGetValue(slug, out var p) ? Pick(p.Title, lang) : "";
        public string Desc(string slug, string lang) => Products.TryGetValue(slug, out var p) ? Pick(p.Desc, lang) : "";
        public string Group(string id, string lang) => GroupTitle.TryGetValue(id, out var m) ? Pick(m, lang) : "";

        public IapProduct ByStoreId(string storeId)
        {
            foreach (var p in Products.Values) if (p.Id == storeId) return p;
            return null;
        }

        public bool GrantsAdFree(string slug)
        {
            if (!Products.TryGetValue(slug, out var p)) return false;
            foreach (string f in AdFreeFeatures) if (p.Grants.Contains(f)) return true;
            return false;
        }

        /// <summary>A permanent product whose every entitlement is active (bought, or covered by a pack).</summary>
        public bool Owned(string slug, Func<string, bool> has)
        {
            if (!Products.TryGetValue(slug, out var p) || p.Consumable || p.Grants.Count == 0 || has == null) return false;
            foreach (string g in p.Grants) if (!has(g)) return false;
            return true;
        }

        public List<string> StoreIds()
        {
            var l = new List<string>();
            foreach (string s in Order) l.Add(Products[s].Id);
            return l;
        }

        public List<string> ConsumableIds()
        {
            var l = new List<string>();
            foreach (string s in Order) if (Products[s].Consumable) l.Add(Products[s].Id);
            return l;
        }
    }
}
